+use crate::error::Error;
+use crate::quote::Report;
+use crate::utils::{
+    parse_x509_chain, verify_certificate_chain, verify_signature,
+};
+use serde::Deserialize;
+
+/// Parsed representation of the fields we care about in the QE Identity
+/// document returned by the PCCS.
+#[derive(Debug, Deserialize)]
+struct QeIdentityBody {
+    #[serde(rename = "issueDate")]
+    issue_date: String,
+    #[serde(rename = "nextUpdate")]
+    next_update: String,
+    #[serde(rename = "miscselect")]
+    miscselect: String,
+    #[serde(rename = "miscselectMask")]
+    miscselect_mask: String,
+    attributes: String,
+    #[serde(rename = "attributesMask")]
+    attributes_mask: String,
+    mrsigner: String,
+    isvprodid: u16,
+    #[serde(rename = "isvsvn")]
+    isvsvn: u16,
+}
+
+#[derive(Debug, Deserialize)]
+struct QeIdentityDoc {
+    #[serde(rename = "enclaveIdentity")]
+    enclave_identity: QeIdentityBody,
+}
+
+fn hex_decode(s: &str) -> Result<Vec<u8>, Error> {
+    hex::decode(s).map_err(|_| Error::InvalidCollateral)
+}
+
+fn apply_mask(value: &[u8], mask: &[u8]) -> Vec<u8> {
+    value.iter().zip(mask.iter()).map(|(v, m)| v & m).collect()
+}
+
+/// Verifies the QE Identity signature against the issuer certificate chain
+/// and enforces the policy constraints contained in the QE Identity
+/// document against the actual QE Report from the quote.
+pub fn verify_qe_identity(
+    qe_identity_json: &str,
+    qe_identity_signature: &[u8],
+    qe_identity_issuer_chain_pem: &str,
+    qe_report: &Report,
+    now: u64,
+    root_ca_crl: &[u8],
+    pck_crl: &[u8],
+) -> Result<(), Error> {
+    // 1. Parse and verify the issuer certificate chain (must chain up to the
+    //    trusted Intel root CA and must not be revoked).
+    let chain = parse_x509_chain(qe_identity_issuer_chain_pem)?;
+    verify_certificate_chain(&chain, root_ca_crl, pck_crl, now)?;
+
+    // 2. Verify the QE Identity signature was produced by the leaf
+    //    certificate in the issuer chain over the raw JSON body.
+    let signing_cert = chain.first().ok_or(Error::InvalidCollateral)?;
+    let public_key = signing_cert.public_key().map_err(|_| Error::InvalidCollateral)?;
+
+    // The signed payload is the raw bytes of the `enclaveIdentity` JSON
+    // object as returned by the PCCS (matching Intel's QVL behavior).
+    let signed_bytes = extract_enclave_identity_bytes(qe_identity_json)?;
+    verify_signature(&signed_bytes, qe_identity_signature, &public_key)?;
+
+    // 3. Parse the identity document and enforce policy.
+    let doc: QeIdentityDoc =
+        serde_json::from_str(qe_identity_json).map_err(|_| Error::InvalidCollateral)?;
+    let body = doc.enclave_identity;
+
+    // 3a. Validity period.
+    let issue_date = chrono::DateTime::parse_from_rfc3339(&body.issue_date)
+        .map_err(|_| Error::InvalidCollateral)?
+        .timestamp();
+    let next_update = chrono::DateTime::parse_from_rfc3339(&body.next_update)
+        .map_err(|_| Error::InvalidCollateral)?
+        .timestamp();
+    let now = now as i64;
+    if now < issue_date || now > next_update {
+        return Err(Error::CollateralExpired);
+    }
+
+    // 3b. ISV SVN must be at least the value certified by Intel.
+    if qe_report.isv_svn < body.isvsvn {
+        return Err(Error::QeIdentityMismatch);
+    }
+
+    // 3c. Masked miscselect must match.
+    let miscselect = hex_decode(&body.miscselect)?;
+    let miscselect_mask = hex_decode(&body.miscselect_mask)?;
+    let masked_expected = apply_mask(&miscselect, &miscselect_mask);
+    let masked_actual = apply_mask(&qe_report.misc_select, &miscselect_mask);
+    if masked_expected != masked_actual {
+        return Err(Error::QeIdentityMismatch);
+    }
+
+    // 3d. Masked attributes must match.
+    let attributes = hex_decode(&body.attributes)?;
+    let attributes_mask = hex_decode(&body.attributes_mask)?;
+    let masked_expected_attr = apply_mask(&attributes, &attributes_mask);
+    let masked_actual_attr = apply_mask(&qe_report.attributes, &attributes_mask);
+    if masked_expected_attr != masked_actual_attr {
+        return Err(Error::QeIdentityMismatch);
+    }
+
+    // 3e. MRSIGNER must match exactly (this is the key check preventing a
+    //     forged/non-Intel QE from being whitelisted).
+    let mrsigner = hex_decode(&body.mrsigner)?;
+    if mrsigner != qe_report.mr_signer {
+        return Err(Error::QeIdentityMismatch);
+    }
+
+    // 3f. ISV Product ID must match.
+    if body.isvprodid != qe_report.isv_prod_id {
+        return Err(Error::QeIdentityMismatch);
+    }
+
+    Ok(())
+}
+
+/// Extracts the raw bytes of the `enclaveIdentity` object from the full
+/// QE Identity JSON, as this is the exact byte range that was signed by
+/// Intel/PCCS.
+fn extract_enclave_identity_bytes(json: &str) -> Result<Vec<u8>, Error> {
+    let value: serde_json::Value =
+        serde_json::from_str(json).map_err(|_| Error::InvalidCollateral)?;
+    let enclave_identity = value
+        .get("enclaveIdentity")
+        .ok_or(Error::InvalidCollateral)?;
+    serde_json::to_vec(enclave_identity).map_err(|_| Error::InvalidCollateral)
+}
