+import java.net.Inet4Address;
+import java.net.Inet6Address;
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.net.UnknownHostException;
+
+/**
+ * Validates endpoints that are used to install pipeline elements in order to
+ * prevent Server-Side Request Forgery (SSRF) attacks (CVE-2024-31979).
+ *
+ * Only http/https URLs pointing to a public, non-loopback, non-link-local
+ * and non-private (RFC1918) address are allowed.
+ */
+public class ExtensionsInstallationValidator {
+
+  private ExtensionsInstallationValidator() {
+  }
+
+  /**
+   * Validates the given endpoint string.
+   *
+   * @param endpoint the endpoint to validate
+   * @throws SecurityException if the endpoint is considered unsafe
+   */
+  public static void validateEndpoint(String endpoint) {
+    if (endpoint == null || endpoint.isBlank()) {
+      throw new SecurityException("Endpoint must not be empty");
+    }
+
+    URI uri;
+    try {
+      uri = new URI(endpoint);
+    } catch (URISyntaxException e) {
+      throw new SecurityException("Invalid endpoint URI: " + endpoint, e);
+    }
+
+    String scheme = uri.getScheme();
+    if (scheme == null || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))) {
+      throw new SecurityException("Only http/https schemes are allowed for endpoint: " + endpoint);
+    }
+
+    String host = uri.getHost();
+    if (host == null || host.isBlank()) {
+      throw new SecurityException("Endpoint must contain a valid host: " + endpoint);
+    }
+
+    InetAddress[] addresses;
+    try {
+      addresses = InetAddress.getAllByName(host);
+    } catch (UnknownHostException e) {
+      throw new SecurityException("Could not resolve host: " + host, e);
+    }
+
+    for (InetAddress address : addresses) {
+      if (isForbiddenAddress(address)) {
+        throw new SecurityException(
+            "Endpoint resolves to a forbidden address (loopback/link-local/private/multicast): " + endpoint);
+      }
+    }
+  }
+
+  private static boolean isForbiddenAddress(InetAddress address) {
+    if (address.isLoopbackAddress()
+        || address.isLinkLocalAddress()
+        || address.isMulticastAddress()
+        || address.isAnyLocalAddress()
+        || address.isSiteLocalAddress()) {
+      return true;
+    }
+
+    if (address instanceof Inet4Address) {
+      byte[] octets = address.getAddress();
+      int first = octets[0] & 0xFF;
+      int second = octets[1] & 0xFF;
+      // 100.64.0.0/10 shared address space
+      if (first == 100 && (second >= 64 && second <= 127)) {
+        return true;
+      }
+      // 169.254.0.0/16 link local (already covered) and 0.0.0.0/8
+      if (first == 0) {
+        return true;
+      }
+    }
+
+    if (address instanceof Inet6Address) {
+      Inet6Address inet6 = (Inet6Address) address;
+      // Unique local addresses fc00::/7
+      byte[] bytes = inet6.getAddress();
+      int firstByte = bytes[0] & 0xFF;
+      if ((firstByte & 0xFE) == 0xFC) {
+        return true;
+      }
+    }
+
+    return false;
+  }
+}
